use std::fmt::Write as _;
use std::path::Path;

use crate::codegen::model::{EventVariantDef, EventsDef, FieldType};

/// Generate `{out_dir}/event_wasm_bindings.rs`.
///
/// The file contains `impl HostModule for EventModule` with a `poll()` function
/// and per-field accessor functions derived from the `WidgetEvent` enum.
/// It is `include!`ed from the wasm executor source file.
pub fn generate_rust(events: &EventsDef, out_dir: &Path) {
    let out_path = out_dir.join("event_wasm_bindings.rs");
    let mut buf = String::new();

    writeln!(
        buf,
        "// AUTO-GENERATED by build/codegen/events.rs — DO NOT EDIT."
    )
    .unwrap();
    writeln!(buf, "// Source: src/widget/mod.rs WidgetEvent enum").unwrap();
    writeln!(buf).unwrap();

    writeln!(buf, "impl HostModule for EventModule {{").unwrap();
    writeln!(buf, "    fn name(&self) -> &str {{ \"event\" }}").unwrap();
    writeln!(buf).unwrap();
    writeln!(buf, "    fn register(").unwrap();
    writeln!(buf, "        &self,").unwrap();
    writeln!(buf, "        linker: &mut Linker<WasmCtx>,").unwrap();
    writeln!(buf, "        store: &mut Store<WasmCtx>,").unwrap();
    writeln!(buf, "    ) -> Result<(), wasmi::Error> {{").unwrap();

    emit_poll(&mut buf, events);

    for variant in &events.variants {
        for field in &variant.fields {
            match &field.ty {
                FieldType::Str => {
                    emit_str_len_accessor(&mut buf, variant, &field.name);
                    emit_str_copy_accessor(&mut buf, variant, &field.name);
                }
                ty => {
                    emit_scalar_accessor(&mut buf, variant, &field.name, ty);
                }
            }
        }
    }

    writeln!(buf).unwrap();
    writeln!(buf, "        Ok(())").unwrap();
    writeln!(buf, "    }}").unwrap();
    writeln!(buf, "}}").unwrap();

    std::fs::write(&out_path, &buf)
        .unwrap_or_else(|e| panic!("cannot write {}: {e}", out_path.display()));
}

fn emit_poll(buf: &mut String, events: &EventsDef) {
    writeln!(buf).unwrap();
    writeln!(buf, "        // --- poll ---").unwrap();
    writeln!(buf, "        linker.define(").unwrap();
    writeln!(buf, "            self.name(),").unwrap();
    writeln!(buf, "            \"poll\",").unwrap();
    writeln!(buf, "            wasmi::Func::wrap(").unwrap();
    writeln!(buf, "                &mut *store,").unwrap();
    writeln!(
        buf,
        "                |mut caller: Caller<'_, WasmCtx>| -> i32 {{"
    )
    .unwrap();
    writeln!(buf, "                    let ctx = caller.data_mut();").unwrap();
    writeln!(
        buf,
        "                    let next = match ctx.event_cursor {{"
    )
    .unwrap();
    writeln!(buf, "                        None => 0,").unwrap();
    writeln!(buf, "                        Some(i) => i + 1,").unwrap();
    writeln!(buf, "                    }};").unwrap();
    writeln!(
        buf,
        "                    if next < ctx.event_queue.len() {{"
    )
    .unwrap();
    writeln!(
        buf,
        "                        ctx.event_cursor = Some(next);"
    )
    .unwrap();
    writeln!(
        buf,
        "                        match &ctx.event_queue[next] {{"
    )
    .unwrap();
    for variant in &events.variants {
        writeln!(
            buf,
            "                            crate::widget::WidgetEvent::{} {{ .. }} => {},",
            variant.name, variant.index
        )
        .unwrap();
    }
    writeln!(buf, "                        }}").unwrap();
    writeln!(buf, "                    }} else {{").unwrap();
    writeln!(buf, "                        -1").unwrap();
    writeln!(buf, "                    }}").unwrap();
    writeln!(buf, "                }},").unwrap();
    writeln!(buf, "            ),").unwrap();
    writeln!(buf, "        )?;").unwrap();
}

fn emit_scalar_accessor(
    buf: &mut String,
    variant: &EventVariantDef,
    field_name: &str,
    ty: &FieldType,
) {
    let func_name = format!("poll_get_{}_{field_name}", to_snake_case(&variant.name));
    let extract = scalar_extract_expr(field_name, ty);

    writeln!(buf).unwrap();
    writeln!(buf, "        // --- {func_name} ---").unwrap();
    writeln!(buf, "        linker.define(").unwrap();
    writeln!(buf, "            self.name(),").unwrap();
    writeln!(buf, "            \"{func_name}\",").unwrap();
    writeln!(buf, "            wasmi::Func::wrap(").unwrap();
    writeln!(buf, "                &mut *store,").unwrap();
    writeln!(
        buf,
        "                |mut caller: Caller<'_, WasmCtx>| -> u32 {{"
    )
    .unwrap();
    writeln!(buf, "                    let ctx = caller.data_mut();").unwrap();
    writeln!(
        buf,
        "                    if let Some(idx) = ctx.event_cursor {{"
    )
    .unwrap();
    writeln!(
        buf,
        "                        if let Some(crate::widget::WidgetEvent::{} {{ {field_name}, .. }}) = ctx.event_queue.get(idx) {{",
        variant.name
    )
    .unwrap();
    writeln!(buf, "                            return {extract};").unwrap();
    writeln!(buf, "                        }}").unwrap();
    writeln!(buf, "                    }}").unwrap();
    writeln!(buf, "                    0").unwrap();
    writeln!(buf, "                }},").unwrap();
    writeln!(buf, "            ),").unwrap();
    writeln!(buf, "        )?;").unwrap();
}

fn emit_str_len_accessor(buf: &mut String, variant: &EventVariantDef, field_name: &str) {
    let func_name = format!("poll_get_{}_{field_name}_len", to_snake_case(&variant.name));

    writeln!(buf).unwrap();
    writeln!(buf, "        // --- {func_name} ---").unwrap();
    writeln!(buf, "        linker.define(").unwrap();
    writeln!(buf, "            self.name(),").unwrap();
    writeln!(buf, "            \"{func_name}\",").unwrap();
    writeln!(buf, "            wasmi::Func::wrap(").unwrap();
    writeln!(buf, "                &mut *store,").unwrap();
    writeln!(
        buf,
        "                |mut caller: Caller<'_, WasmCtx>| -> u32 {{"
    )
    .unwrap();
    writeln!(buf, "                    let ctx = caller.data_mut();").unwrap();
    writeln!(
        buf,
        "                    if let Some(idx) = ctx.event_cursor {{"
    )
    .unwrap();
    writeln!(
        buf,
        "                        if let Some(crate::widget::WidgetEvent::{} {{ {field_name}, .. }}) = ctx.event_queue.get(idx) {{",
        variant.name
    )
    .unwrap();
    writeln!(
        buf,
        "                            return {field_name}.len() as u32;"
    )
    .unwrap();
    writeln!(buf, "                        }}").unwrap();
    writeln!(buf, "                    }}").unwrap();
    writeln!(buf, "                    0").unwrap();
    writeln!(buf, "                }},").unwrap();
    writeln!(buf, "            ),").unwrap();
    writeln!(buf, "        )?;").unwrap();
}

fn emit_str_copy_accessor(buf: &mut String, variant: &EventVariantDef, field_name: &str) {
    let func_name = format!("poll_get_{}_{field_name}", to_snake_case(&variant.name));

    writeln!(buf).unwrap();
    writeln!(buf, "        // --- {func_name} ---").unwrap();
    writeln!(buf, "        linker.define(").unwrap();
    writeln!(buf, "            self.name(),").unwrap();
    writeln!(buf, "            \"{func_name}\",").unwrap();
    writeln!(buf, "            wasmi::Func::wrap(").unwrap();
    writeln!(buf, "                &mut *store,").unwrap();
    writeln!(
        buf,
        "                |mut caller: Caller<'_, WasmCtx>, ptr: u32| {{"
    )
    .unwrap();
    writeln!(
        buf,
        "                    let bytes: alloc::vec::Vec<u8> = {{"
    )
    .unwrap();
    writeln!(buf, "                        let ctx = caller.data_mut();").unwrap();
    writeln!(
        buf,
        "                        if let Some(idx) = ctx.event_cursor {{"
    )
    .unwrap();
    writeln!(
        buf,
        "                            if let Some(crate::widget::WidgetEvent::{} {{ {field_name}, .. }}) = ctx.event_queue.get(idx) {{",
        variant.name
    )
    .unwrap();
    writeln!(
        buf,
        "                                {field_name}.as_bytes().to_vec()"
    )
    .unwrap();
    writeln!(buf, "                            }} else {{ return; }}").unwrap();
    writeln!(buf, "                        }} else {{ return; }}").unwrap();
    writeln!(buf, "                    }};").unwrap();
    writeln!(
        buf,
        "                    let memory = match caller.get_export(\"memory\") {{"
    )
    .unwrap();
    writeln!(
        buf,
        "                        Some(wasmi::Extern::Memory(m)) => m,"
    )
    .unwrap();
    writeln!(buf, "                        _ => return,").unwrap();
    writeln!(buf, "                    }};").unwrap();
    writeln!(
        buf,
        "                    let _ = memory.write(&mut caller, ptr as usize, &bytes);"
    )
    .unwrap();
    writeln!(buf, "                }},").unwrap();
    writeln!(buf, "            ),").unwrap();
    writeln!(buf, "        )?;").unwrap();
}

fn scalar_extract_expr(field_name: &str, ty: &FieldType) -> String {
    match ty {
        FieldType::U32 | FieldType::Usize => format!("*{field_name} as u32"),
        FieldType::TimerId => format!("{field_name}.0 as u32"),
        FieldType::Bool => format!("if *{field_name} {{ 1u32 }} else {{ 0u32 }}"),
        FieldType::Duration => format!("{field_name}.as_ticks() as u32"),
        FieldType::Str => unreachable!("Str fields are handled separately"),
        _ => format!("*{field_name} as u32"),
    }
}

/// Generate `widgets/events.ts` with per-variant event classes and a `pollEvent()` function.
pub fn generate_ts(events: &EventsDef, out_path: &Path) {
    let mut buf = String::new();

    writeln!(
        buf,
        "// AUTO-GENERATED by build/codegen/events.rs — DO NOT EDIT."
    )
    .unwrap();
    writeln!(buf).unwrap();

    // 1. Internal WASM import namespace
    writeln!(buf, "declare namespace event {{").unwrap();
    writeln!(buf, "  @external(\"event\", \"poll\")").unwrap();
    writeln!(buf, "  function poll(): i32;").unwrap();
    for variant in &events.variants {
        let variant_snake = to_snake_case(&variant.name);
        for field in &variant.fields {
            let fn_name = format!("poll_get_{variant_snake}_{}", field.name);
            match &field.ty {
                FieldType::Str => {
                    let len_fn = format!("{fn_name}_len");
                    writeln!(buf, "  @external(\"event\", \"{len_fn}\")").unwrap();
                    writeln!(buf, "  function {len_fn}(): u32;").unwrap();
                    writeln!(buf, "  @external(\"event\", \"{fn_name}\")").unwrap();
                    writeln!(buf, "  function {fn_name}(ptr: usize): void;").unwrap();
                }
                _ => {
                    writeln!(buf, "  @external(\"event\", \"{fn_name}\")").unwrap();
                    writeln!(buf, "  function {fn_name}(): u32;").unwrap();
                }
            }
        }
    }
    writeln!(buf, "}}").unwrap();
    writeln!(buf).unwrap();

    // 2. Event type index constants
    for variant in &events.variants {
        let const_name = to_screaming_snake(&variant.name);
        writeln!(
            buf,
            "export const EVENT_{const_name}: i32 = {};",
            variant.index
        )
        .unwrap();
    }
    writeln!(buf).unwrap();

    // 3. Abstract base class
    writeln!(buf, "export abstract class WidgetEvent {{").unwrap();
    writeln!(buf, "  readonly type: i32;").unwrap();
    writeln!(buf, "  constructor(type: i32) {{ this.type = type; }}").unwrap();
    writeln!(buf, "}}").unwrap();
    writeln!(buf).unwrap();

    // 4. Per-variant event classes
    for variant in &events.variants {
        let class_name = format!("{}Event", variant.name);
        let const_name = to_screaming_snake(&variant.name);

        writeln!(buf, "export class {class_name} extends WidgetEvent {{").unwrap();

        // Field declarations
        for field in &variant.fields {
            let field_ts = to_lower_camel_case(&field.name);
            let ty = ts_field_type(&field.ty);
            writeln!(buf, "  readonly {field_ts}: {ty};").unwrap();
        }

        // Constructor
        let ctor_params = variant
            .fields
            .iter()
            .map(|f| format!("{}: {}", to_lower_camel_case(&f.name), ts_field_type(&f.ty)))
            .collect::<Vec<_>>()
            .join(", ");
        writeln!(buf, "  constructor({ctor_params}) {{").unwrap();
        writeln!(buf, "    super(EVENT_{const_name});").unwrap();
        for field in &variant.fields {
            let field_ts = to_lower_camel_case(&field.name);
            writeln!(buf, "    this.{field_ts} = {field_ts};").unwrap();
        }
        writeln!(buf, "  }}").unwrap();
        writeln!(buf, "}}").unwrap();
        writeln!(buf).unwrap();
    }

    // 5. pollEvent() function
    writeln!(
        buf,
        "// Poll the next event from the queue and reconstruct it as a typed object."
    )
    .unwrap();
    writeln!(buf, "// Returns null when there are no more events.").unwrap();
    writeln!(buf, "export function pollEvent(): WidgetEvent | null {{").unwrap();
    writeln!(buf, "  const type = event.poll();").unwrap();

    for variant in &events.variants {
        let variant_snake = to_snake_case(&variant.name);
        let class_name = format!("{}Event", variant.name);
        let const_name = to_screaming_snake(&variant.name);

        writeln!(buf, "  if (type == EVENT_{const_name}) {{").unwrap();

        // Read each field into a local variable
        for field in &variant.fields {
            let field_ts = to_lower_camel_case(&field.name);
            let fn_name = format!("poll_get_{variant_snake}_{}", field.name);
            match &field.ty {
                FieldType::Str => {
                    let len_fn = format!("{fn_name}_len");
                    writeln!(buf, "    const __{}_len = event.{len_fn}();", field.name).unwrap();
                    writeln!(
                        buf,
                        "    const __{}_buf = new Uint8Array(__{}_len);",
                        field.name, field.name
                    )
                    .unwrap();
                    writeln!(buf, "    event.{fn_name}(__{}_buf.dataStart);", field.name).unwrap();
                    writeln!(
                        buf,
                        "    const {field_ts} = String.UTF8.decode(__{}_buf.buffer);",
                        field.name
                    )
                    .unwrap();
                }
                _ => {
                    writeln!(buf, "    const {field_ts} = event.{fn_name}();").unwrap();
                }
            }
        }

        // Construct and return the event object
        let ctor_args = variant
            .fields
            .iter()
            .map(|f| to_lower_camel_case(&f.name))
            .collect::<Vec<_>>()
            .join(", ");
        writeln!(buf, "    return new {class_name}({ctor_args});").unwrap();
        writeln!(buf, "  }}").unwrap();
    }

    writeln!(buf, "  return null;").unwrap();
    writeln!(buf, "}}").unwrap();

    std::fs::write(out_path, &buf)
        .unwrap_or_else(|e| panic!("cannot write {}: {e}", out_path.display()));
}

fn ts_field_type(ty: &FieldType) -> &'static str {
    match ty {
        FieldType::U32 | FieldType::Usize | FieldType::TimerId => "u32",
        FieldType::Bool => "bool",
        FieldType::Str => "string",
        FieldType::Duration => "u64",
        _ => "u32",
    }
}

fn to_lower_camel_case(s: &str) -> String {
    let camel = to_camel_case(s);
    let mut chars = camel.chars();
    match chars.next() {
        None => String::new(),
        Some(f) => f.to_ascii_lowercase().to_string() + chars.as_str(),
    }
}

fn to_snake_case(s: &str) -> String {
    // "TimerInterrupt" → "timer_interrupt"
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if c.is_uppercase() && i > 0 {
            result.push('_');
        }
        result.push(c.to_ascii_lowercase());
    }
    result
}

fn to_screaming_snake(s: &str) -> String {
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if c.is_uppercase() && i > 0 {
            result.push('_');
        }
        result.push(c.to_ascii_uppercase());
    }
    result
}

fn to_camel_case(s: &str) -> String {
    s.split('_')
        .map(|w| {
            let mut c = w.chars();
            match c.next() {
                None => String::new(),
                Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
            }
        })
        .collect()
}
